	('6915a553-7f1a-4062-8485-dcf12a8fa645', 'b1044557-0cd0-4c4c-b3cb-842afa35f490', 'not_specified', NULL, NULL, NULL, NULL, false, 'seller_declared', '2026-07-25 14:09:00.864122+00', '2026-07-25 14:10:46.81842+00'),
	('7ca0c350-a99d-4118-9f0f-d046bf9d54c0', 'f571033d-c4ab-46d5-92f2-ef50c09f9bd0', 'pre_loved', 'Vải canvas và da lộn (suede)', NULL, NULL, 'Đôi giày đã qua một chủ sở hữu, được bảo quản trong hộp gốc và không sửa chữa gì thêm.', true, 'seller_declared', '2026-07-21 13:34:57.32443+00', '2026-07-21 15:31:01.847841+00'),
	('5ae1ec26-23d2-4c89-ab42-fffb53d57cc3', '52e2a7ad-6b1f-48ec-bcb9-e5a9ac8b4a88', 'pre_loved', 'Da tổng hợp và cao su', NULL, NULL, 'Đôi giày đã mang vài lần ngoài trời, được vệ sinh trước khi đăng bán.', true, 'seller_declared', '2026-07-21 13:34:58.640501+00', '2026-07-21 15:31:02.196756+00'),
	('591a1b5d-1bbb-4842-abf1-71a1289c24ff', 'b20bf8c0-5e85-4719-a0a1-df4375032c52', 'deadstock', 'Da thật và cao su', NULL, NULL, 'Giày là hàng lưu kho cũ chưa từng bán ra, còn nguyên thẻ bài như trong ảnh.', false, 'seller_declared', '2026-07-21 13:34:59.587524+00', '2026-07-21 15:31:02.46556+00'),
	('896d0c3a-b0e7-4280-a3c0-597ecb14b90d', '127531b0-4e93-4755-970b-41995918234e', 'repaired', 'Da thật (leather) AirWair', 'Đã thay đế ngoài (resole) và khâu lại đường chỉ mũi giày tại một thợ đóng giày địa phương vào đầu năm nay.', NULL, 'Đôi boots được giữ dùng lâu dài thay vì bỏ đi khi mòn đế, nên đã mang đi sửa.', false, 'seller_declared', '2026-07-21 13:35:01.206984+00', '2026-07-21 15:31:02.735852+00'),
	('fea99fc7-46d2-49f5-af68-2e19cb58c0d5', 'f963c40d-2287-4683-84f1-1c067b71b3b3', 'deadstock', 'Da và vải mesh', NULL, NULL, 'Giày là hàng mẫu cửa hàng cũ chưa từng bán ra, được thanh lý nguyên trạng.', true, 'seller_declared', '2026-07-21 13:35:02.627328+00', '2026-07-21 15:31:03.009942+00'),
	('2193c220-69c5-4a14-89b9-96b5ebcba4cd', 'ffec5f14-fecf-41a4-872b-f526c82bf688', 'pre_loved', 'Đế lie (cork) và da', NULL, NULL, 'Dép được dùng trong nhà, ít tiếp xúc nước, còn giữ phom đế.', false, 'seller_declared', '2026-07-21 13:35:03.580509+00', '2026-07-21 15:31:03.351554+00'),
	('fb03bb89-d5bd-4211-abb0-0640e4c39497', 'bce0b07e-6b2c-4933-a676-5eff6af717a2', 'repaired', 'Da quilted (chần bông)', 'Đã thay móc khóa kim loại bị gãy và khâu lại quai đeo bị bung chỉ tại thợ sửa đồ da.', NULL, 'Túi được sửa để tiếp tục sử dụng thay vì bỏ đi khi phụ kiện hỏng.', true, 'seller_declared', '2026-07-21 13:35:04.826091+00', '2026-07-21 15:31:03.621225+00'),
	('5bfc2363-d1f5-4ad8-b056-4cb3acbe27df', '67d32eaa-bd48-4b6c-bad3-d1548c960883', 'upcycled', 'Da thuộc tái sử dụng', NULL, 'Túi được làm lại từ các mảnh da thuộc còn dư sau sản xuất, thay khoá kéo và dây quai da mới để kéo dài vòng đời sử dụng.', 'Đây là sản phẩm của một xưởng nhỏ độc lập chuyên tái thiết kế đồ da cũ.', true, 'seller_declared', '2026-07-21 13:35:06.067276+00', '2026-07-21 15:31:03.886224+00'),
	('5c6c3a0a-864f-4195-b3e1-a2bd0f0f0c51', '6f4bb9ed-80de-405b-9437-12f52ac0eab5', 'upcycled', 'Vải canvas và denim tái chế', NULL, 'Túi tote canvas gốc được phối thêm mảnh vải jeans cũ và một patch thêu tay thủ công để kéo dài vòng đời sử dụng.', 'Đây là một lô nhỏ được làm lại thủ công từ vải denim còn dư, không phải sản xuất hàng loạt.', true, 'seller_declared', '2026-07-21 13:35:07.272118+00', '2026-07-21 15:31:04.138955+00'),
	('b3fb3bc2-ad86-4fdd-8270-928eb647c0e8', 'bcf371f7-6713-419d-b107-cffa0330e955', 'pre_loved', 'Da tổng hợp (vegan leather)', NULL, NULL, 'Túi được dùng khoảng 6 tháng, bảo quản trong túi vải kèm theo.', false, 'seller_declared', '2026-07-21 13:35:08.305926+00', '2026-07-21 15:31:04.39615+00'),
	('1d31d219-771f-443a-b5ad-1f748af96778', '0efb498f-fce3-4695-8fa6-7d165042269e', 'new', 'Cotton 100%', NULL, NULL, 'Sản phẩm mới, chưa qua sử dụng.', false, 'seller_declared', '2026-07-21 13:35:09.605857+00', '2026-07-21 15:31:04.682783+00'),
